insert into app.chapters (id, title_en, title_ru, text_en, text_ru) values
 (1, 'Hello, neighbours', 'Здравствуйте, соседи', 'New in the city. The first step is the hardest: say hello, open your door, find one friend.', 'Вы новенький в городе. Первый шаг самый трудный: поздороваться, открыть дверь, найти друга.'),
 (2, 'Finding your people', 'Свои люди', 'A city of millions, and you need a few people who will answer at night.', 'Город-миллионник, а нужны несколько человек, которые ответят и ночью.'),
 (3, 'Open doors', 'Открытые двери', 'Visit homes, leave kind words and small gifts. Hospitality is how you belong.', 'Ходите в гости, оставляйте добрые слова и маленькие подарки. Гостеприимство — это как свои.'),
 (4, 'The market square', 'Рыночная площадь', 'Rooms, jobs, a coat that no longer fits: everything starts with an advert and a conversation.', 'Комнаты, работа, пальто, которое мало: всё начинается с объявления и разговора.'),
 (5, 'Speaking Russian', 'Говорим по-русски', 'Every word in Russian is a door. Practise with real people.', 'Каждое слово по-русски — это дверь. Практикуйтесь с живыми людьми.'),
 (6, 'The first winter', 'Первая зима', 'Snow, short days and long evenings. Winter is easier together.', 'Снег, короткие дни и долгие вечера. Зимой легче вместе.'),
 (7, 'A voice in the city', 'Голос в городе', 'Vote, help newcomers, clean the park: the city becomes yours.', 'Голосуйте, помогайте новичкам, убирайте парк — и город станет вашим.'),
 (8, 'Known across Russia', 'Известны по всей России', 'From Kaliningrad to Vladivostok, people know your name.', 'От Калининграда до Владивостока знают ваше имя.');
